import json
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


class Client:
    def __init__(self, log_path, max_attempts=200):
        self.token = None
        self.log_path = log_path
        self.max_attempts = max_attempts
        self.stats = {"requests": 0, "token_fetches": 0, "status": {}}

    def _log(self, **rec):
        rec["t"] = time.time()
        with open(self.log_path, "a") as f:
            f.write(json.dumps(rec) + "\n")

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method)
        if auth and self.token:
            req.add_header("Authorization", "Bearer " + self.token)
        if method == "POST":
            req.data = b""
        self.stats["requests"] += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers or {}), e.read()

    @staticmethod
    def _wait_seconds(headers, body_obj):
        """Wait time the server asked for, from header or body."""
        for k, v in headers.items():
            if k.lower() == "retry-after":
                try:
                    return float(v)
                except ValueError:
                    pass
        if isinstance(body_obj, dict):
            for key in ("retry_after", "retry_after_seconds", "wait", "wait_seconds"):
                if key in body_obj:
                    try:
                        return float(body_obj[key])
                    except (TypeError, ValueError):
                        pass
            for key in ("retry_after_ms", "wait_ms"):
                if key in body_obj:
                    try:
                        return float(body_obj[key]) / 1000.0
                    except (TypeError, ValueError):
                        pass
        return None

    def request(self, method, path, auth=True, validate=None):
        """Return (status, parsed_json) for a successful 200 (or 404), retrying otherwise.

        validate(obj) -> error string or None; a non-None result triggers a retry.
        """
        for attempt in range(1, self.max_attempts + 1):
            if auth and not self.token:
                self.refresh_token()
            try:
                status, headers, body = self._raw(method, path, auth)
            except Exception as e:  # connection reset, timeout, etc.
                self._log(path=path, attempt=attempt, kind="exception", error=repr(e))
                time.sleep(min(0.5 * attempt, 5))
                continue
            self.stats["status"][status] = self.stats["status"].get(status, 0) + 1
            text = body.decode("utf-8", errors="replace")
            try:
                obj = json.loads(text)
            except ValueError:
                obj = None

            if status == 200:
                if obj is None:
                    self._log(path=path, attempt=attempt, kind="bad_json", status=status,
                              headers=headers, body=text[:500])
                    time.sleep(0.2)
                    continue
                err = validate(obj) if validate else None
                if err:
                    self._log(path=path, attempt=attempt, kind="invalid", status=status,
                              error=err, body=text[:500])
                    time.sleep(0.2)
                    continue
                return status, obj

            self._log(path=path, attempt=attempt, kind="http", status=status,
                      headers=headers, body=text[:500])
            if status == 401 and auth:
                self.refresh_token()
                continue
            if status == 429:
                wait = self._wait_seconds(headers, obj)
                if wait is None:
                    wait = 2.0
                time.sleep(wait + 0.05)
                continue
