                return status, obj
            # 5xx or anything else: retry after a short pause
            time.sleep(min(0.5 * attempt, 5))
        raise RuntimeError(f"gave up on {method} {path} after {self.max_attempts} attempts")

    def refresh_token(self):
        def ok(obj):
            if not isinstance(obj, dict) or not isinstance(obj.get("token"), str) or not obj["token"]:
                return "no token in body"
            return None
        self.stats["token_fetches"] += 1
        _, obj = self.request("POST", "/token", auth=False, validate=ok)
        self.token = obj["token"]
        self._log(kind="new_token", token=self.token)

