"""Fetch each distinct customer referenced by the orders exactly once (plus 404 confirmation)."""
import glob
import json
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from apiclient import Client  # noqa: E402

data_dir = sys.argv[1]
client = Client(os.path.join(data_dir, "customers_log.jsonl"))

ids = set()
for fp in glob.glob(os.path.join(data_dir, "pages", "page_*.json")):
    for it in json.load(open(fp))["items"]:
        ids.add(it["customer_id"])
ids = sorted(ids)
print("distinct customers to fetch:", len(ids), flush=True)


def make_validator(cid):
    def validate(obj):
        if not isinstance(obj, dict):
            return "not an object"
        missing = {"id", "region", "discount_pct"} - set(obj)
        if missing:
            return f"missing keys {sorted(missing)}"
        if obj["id"] != cid:
            return f"id {obj['id']!r} != requested {cid!r}"
        return None
    return validate


customers = {}
for i, cid in enumerate(ids, 1):
    status, obj = client.request("GET", f"/customers/{cid}", validate=make_validator(cid))
    if status == 404:
        # confirm it is persistent, not transient
        confirmations = []
        for _ in range(3):
            time.sleep(0.5)
            s2, o2 = client.request("GET", f"/customers/{cid}", validate=make_validator(cid))
            confirmations.append(s2)
            if s2 == 200:
                status, obj = s2, o2
                break
        if status == 404:
            customers[cid] = {"_status": 404, "_body": obj, "_confirmations": confirmations}
            print(f"{i}/{len(ids)} {cid}: 404 (confirmed x{len(confirmations)})", flush=True)
            continue
    customers[cid] = obj
    if i % 20 == 0:
        print(f"{i}/{len(ids)} fetched", flush=True)

with open(os.path.join(data_dir, "customers.json"), "w") as f:
    json.dump(customers, f, indent=1, sort_keys=True)
print("stats:", json.dumps(client.stats))

